<?php require __DIR__.'/_header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='delete'){db()->prepare('DELETE FROM programs WHERE id=?')->execute([(int)$_POST['id']]);flash('Programme deleted.');}else{$t=trim($_POST['title']??'');$d=trim($_POST['description']??'');if($t&&$d){db()->prepare('INSERT INTO programs(title,description,status) VALUES(?,?,?)')->execute([$t,$d,'Active']);flash('Programme added.');}else flash('Please provide a title and description.','error');}header('Location: programs.php');exit;}
$rows=db()->query('SELECT * FROM programs ORDER BY id DESC')->fetchAll();?>
<div class="admin-heading"><div><span class="eyebrow">ACTIVITIES</span><h1>Programmes</h1><p>Publish the programmes displayed on the website.</p></div></div>
<form method="post" class="form-card admin-form"><?=csrf_field()?><h2>Add programme</h2><label>Programme title<input name="title" required></label><label>Description<textarea name="description" rows="4" required></textarea></label><button class="btn btn-dark">Publish programme</button></form>
<div class="table-wrap"><table><thead><tr><th>Programme</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['status'])?></td><td><form method="post" onsubmit="return confirm('Delete this programme?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="small-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php require __DIR__.'/_footer.php'; ?>